package rules

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
)

//go:embed data/fr-graphs.json.gz
var frenchCompiledGraphs []byte

// FrenchGraphs returns an independent copy of the embedded French token graphs,
// generated by CompileGraphs from FrenchSource. The source and native compiler
// remain available to regenerate the resource without external tooling.
func FrenchGraphs() ([]CompiledGraph, error) {
	reader, err := gzip.NewReader(bytes.NewReader(frenchCompiledGraphs))
	if err != nil {
		return nil, err
	}
	defer reader.Close()
	var graphs []CompiledGraph
	err = json.NewDecoder(reader).Decode(&graphs)
	return graphs, err
}
